tool_schemas.implementation:
def generate_images(workspace_id, api_key_id, request_payload, model=None, execute=None, idempotency_key=None, **_extra):
    import json, os, datetime, re, time, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0419000" if __import__("os").path.isdir("./environment_mix/0419000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_isoz(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _minute_bucket(dt):
        return dt.replace(second=0, microsecond=0)

    def _today(dt):
        return dt.date()

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        tms = int(now_dt.timestamp() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[tms % 32])
            tms //= 32
        timepart = "".join(reversed(chars))
        randpart = "".join(secrets.choice(alphabet) for _ in range(16))
        return f"{prefix}_{timepart}{randpart}"

    def _log(endpoint, status, credential_id=None, workspace=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "workspace_id": workspace,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # --- validate inputs ---
    wsp_pat = re.compile(r"^imgwsp_[0-9A-HJKMNP-TV-Z]{16,}$")
    key_pat = re.compile(r"^imgkey_[0-9A-HJKMNP-TV-Z]{16,}$")
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        _log("generate_images", "error", credential_id=None, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")
    if not isinstance(api_key_id, str) or not key_pat.match(api_key_id):
        _log("generate_images", "error", credential_id=None, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key_id is malformed.", field="api_key_id")
    if not isinstance(request_payload, dict):
        _log("generate_images", "error", credential_id=api_key_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "request_payload must be an object.", field="request_payload")
    if model is None:
        model = "gemini-imagen-3.0"
    if model != "gemini-imagen-3.0":
        _log("generate_images", "error", credential_id=api_key_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unsupported model.", field="model", allowed=["gemini-imagen-3.0"])
    if execute is None:
        execute = True
    if not isinstance(execute, bool):
        _log("generate_images", "error", credential_id=api_key_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "execute must be a boolean.", field="execute")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log("generate_images", "error", credential_id=api_key_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "idempotency_key must be a string.", field="idempotency_key")

    # --- load data ---
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    jobs = _load("image_generation_jobs.json")
    artifacts = _load("image_artifacts.json")

    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(jobs, list): jobs = []
    if not isinstance(artifacts, list): artifacts = []

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log("generate_images", "error", credential_id=api_key_id, workspace=workspace_id, meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") == "deleted":
        _log("generate_images", "error", credential_id=api_key_id, workspace=workspace_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is deleted; writes are forbidden.", workspace_id=workspace_id)

    # authenticate api_key_id against api_keys.id (client-visible) or allow fallback to any active key in workspace
    key_row = None
    direct = next((k for k in api_keys if k.get("id") == api_key_id), None)
    if direct and direct.get("workspace_id") == workspace_id:
        key_row = direct
    else:
        # Search for a usable combination rather than failing immediately
        key_row = next((k for k in api_keys if k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
        if not key_row:
            _log("generate_images", "error", credential_id=api_key_id, workspace=workspace_id, meta={"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "No active API key available for this workspace.", api_key_id=api_key_id, workspace_id=workspace_id)
    # now "used credential" is key_row
    used_cred_id = key_row.get("id")

    if key_row.get("status") != "active":
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is revoked; cannot create or execute jobs.", api_key_id=used_cred_id)

    # idempotency: look up by deterministic fingerprint derived from idempotency_key+workspace+key+model
    if idempotency_key:
        fp = hashlib.sha256((workspace_id + "|" + used_cred_id + "|" + model + "|" + idempotency_key).encode("utf-8")).hexdigest()
        existing = next((j for j in jobs if j.get("workspace_id") == workspace_id and j.get("api_key_id") == used_cred_id and j.get("model") == model and isinstance(j.get("request_payload"), dict) and j["request_payload"].get("_idempotency_fp") == fp), None)
        if existing:
            job_id = existing.get("id")
            job_artifacts = [a for a in artifacts if a.get("workspace_id") == workspace_id and a.get("job_id") == job_id]
            _log("generate_images", "ok", credential_id=used_cred_id, workspace=workspace_id, meta={"idempotent": True})
            return {"job": existing, "artifacts": job_artifacts, "idempotent": True}

    # enforce rate limit + quotas for generate_images (creation counts too)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    rpm_limit = key_row.get("requests_per_minute_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1 or rpm_limit > 6000:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "API key has invalid requests_per_minute_limit.", api_key_id=used_cred_id)
    bucket = _minute_bucket(now_dt)
    used_in_bucket = 0
    for r in logs:
        if r.get("credential_id") != used_cred_id:
            continue
        ts = _parse_isoz(r.get("timestamp"))
        if not ts:
            continue
        if _minute_bucket(ts) == bucket:
            used_in_bucket += 1
    if used_in_bucket >= rpm_limit:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "RATE_LIMIT"})
        return _err("RATE_LIMIT", "Rate limit exceeded for API key.", api_key_id=used_cred_id, retry_after_seconds=60)

    daily_job_limit = key_row.get("daily_job_limit")
    if not isinstance(daily_job_limit, int) or daily_job_limit < 0 or daily_job_limit > 100000:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "API key has invalid daily_job_limit.", api_key_id=used_cred_id)
    if daily_job_limit == 0:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily job limit exceeded for API key.", api_key_id=used_cred_id, error_code="quota_daily_jobs")

    created_today = 0
    for j in jobs:
        if j.get("api_key_id") != used_cred_id:
            continue
        if j.get("workspace_id") != workspace_id:
            continue
        qa = _parse_isoz(j.get("queued_at")) or _parse_isoz(j.get("created_at"))
        if qa and _today(qa) == _today(now_dt):
            created_today += 1
    if created_today >= daily_job_limit:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily job limit exceeded for API key.", api_key_id=used_cred_id, error_code="quota_daily_jobs")

    # Determine requested number of images for daily_image_limit
    n_images = 1
    if isinstance(request_payload.get("n"), int):
        n_images = request_payload.get("n")
    elif isinstance(request_payload.get("num_images"), int):
        n_images = request_payload.get("num_images")
    elif isinstance(request_payload.get("number_of_images"), int):
        n_images = request_payload.get("number_of_images")
    if not isinstance(n_images, int) or n_images < 1 or n_images > 50:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Requested number of images is invalid; must be between 1 and 50.", field="request_payload", detail="n/num_images/number_of_images")

    daily_image_limit = key_row.get("daily_image_limit")
    if not isinstance(daily_image_limit, int) or daily_image_limit < 0 or daily_image_limit > 1000000:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "API key has invalid daily_image_limit.", api_key_id=used_cred_id)
    if daily_image_limit == 0:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily image quota exceeded for API key/workspace.", api_key_id=used_cred_id, error_code="quota_daily_images")

    images_today = 0
    for a in artifacts:
        if a.get("workspace_id") != workspace_id:
            continue
        # count only artifacts from jobs created under this key
        ajob = next((j for j in jobs if j.get("id") == a.get("job_id")), None)
        if not ajob or ajob.get("api_key_id") != used_cred_id:
            continue
        ca = _parse_isoz(a.get("created_at"))
        if ca and _today(ca) == _today(now_dt) and a.get("status") == "available":
            images_today += 1
    if images_today + n_images > daily_image_limit:
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily image quota exceeded for API key/workspace.", api_key_id=used_cred_id, error_code="quota_daily_images")

    # Create job (queued)
    job_id = _gen_id("imgjob")
    req_payload_to_store = dict(request_payload)
    if idempotency_key:
        fp = hashlib.sha256((workspace_id + "|" + used_cred_id + "|" + model + "|" + idempotency_key).encode("utf-8")).hexdigest()
        req_payload_to_store["_idempotency_fp"] = fp
    job = {
        "id": job_id,
        "workspace_id": workspace_id,
        "api_key_id": used_cred_id,
        "status": "queued",
        "model": model,
        "request_payload": req_payload_to_store,
        "response_payload": None,
        "provider_request_id": None,
        "error_code": None,
        "error_message": None,
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)
    _save("image_generation_jobs.json", jobs)

    # update key last_used_at
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    # If execute=false, return queued job without further transitions
    if not execute:
        _log("generate_images", "ok", credential_id=used_cred_id, workspace=workspace_id, meta={"executed": False})
        return {"job": job, "artifacts": []}

    # Workspace suspended: may create queued but must not transition to running
    if ws.get("status") == "suspended":
        _log("generate_images", "ok", credential_id=used_cred_id, workspace=workspace_id, meta={"executed": False, "note": "workspace_suspended"})
        return {"job": job, "artifacts": []}

    # Transition queued -> running
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now
    _save("image_generation_jobs.json", jobs)

    # "Execute" locally: create placeholder artifacts and mark job succeeded.
    # Enforce unique(workspace_id, file_path) and root under storage_base_path.
    base = ws.get("storage_base_path")
    if not isinstance(base, str) or base.strip() == "":
        job["status"] = "failed"
        job["error_code"] = "invalid_storage_base_path"
        job["error_message"] = "Workspace storage_base_path is invalid."
        job["finished_at"] = now
        job["updated_at"] = now
        _save("image_generation_jobs.json", jobs)
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Workspace storage_base_path is invalid.", workspace_id=workspace_id)

    base_abs = os.path.abspath(base)
    os.makedirs(base_abs, exist_ok=True)

    def _under_base(path_abs):
        try:
            return os.path.commonpath([base_abs, path_abs]) == base_abs
        except Exception:
            return False

    created_artifacts = []
    failed = None
    for i in range(n_images):
        art_id = _gen_id("imgart")
        file_name = f"{job_id}_{i}.png"
        file_path_abs = os.path.abspath(os.path.join(base_abs, file_name))
        if not _under_base(file_path_abs):
            failed = _err("VALIDATION_ERROR", "Computed file path escapes workspace storage base path.", workspace_id=workspace_id)
            break
        # uniqueness per workspace
        if any(a.get("workspace_id") == workspace_id and a.get("file_path") == file_path_abs for a in artifacts):
            # extremely unlikely; retry with random suffix
            file_name = f"{job_id}_{i}_{secrets.token_hex(4)}.png"
            file_path_abs = os.path.abspath(os.path.join(base_abs, file_name))
            if any(a.get("workspace_id") == workspace_id and a.get("file_path") == file_path_abs for a in artifacts) or not _under_base(file_path_abs):
                failed = _err("CONFLICT", "Could not allocate unique file_path for artifact.", workspace_id=workspace_id)
                break
        try:
            with open(file_path_abs, "wb") as f:
                f.write(b"\x89PNG\r\n\x1a\n")  # PNG signature only (placeholder)
        except OSError as e:
            failed = _err("CONFLICT", "Failed to write artifact file.", detail=str(e))
            break

        byte_size = 8
        art = {
            "id": art_id,
            "workspace_id": workspace_id,
            "job_id": job_id,
            "status": "available",
            "file_path": file_path_abs,
            "file_name": file_name,
            "mime_type": "image/png",
            "byte_size": byte_size,
            "width": None,
            "height": None,
            "sha256": hashlib.sha256(b"\x89PNG\r\n\x1a\n").hexdigest(),
            "sort_order": i,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None
        }
        artifacts.append(art)
        created_artifacts.append(art)

    if failed:
        # mark any created artifacts as deleted (no available artifacts may be created on failure)
        for a in created_artifacts:
            a["status"] = "deleted"
            a["deleted_at"] = now
            a["updated_at"] = now
        _save("image_artifacts.json", artifacts)

        job["status"] = "failed"
        job["error_code"] = "artifact_write_failed"
        job["error_message"] = failed["error"]["message"]
        job["finished_at"] = now
        job["updated_at"] = now
        _save("image_generation_jobs.json", jobs)

        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": failed["error"]["code"]})
        return failed

    # success: must have at least one available artifact
    if not created_artifacts:
        job["status"] = "failed"
        job["error_code"] = "no_artifacts"
        job["error_message"] = "Job produced no artifacts."
        job["finished_at"] = now
        job["updated_at"] = now
        _save("image_generation_jobs.json", jobs)
        _log("generate_images", "error", credential_id=used_cred_id, workspace=workspace_id, meta={"code": "CONFLICT"})
        return _err("CONFLICT", "Job produced no artifacts; invariant violation.", job_id=job_id)

    job["status"] = "succeeded"
    job["response_payload"] = {
        "artifacts": [{"id": a["id"], "file_path": a["file_path"], "mime_type": a["mime_type"]} for a in created_artifacts],
        "latency_ms": int((time.time() - t0) * 1000)
    }
    job["provider_request_id"] = "prov_" + secrets.token_hex(10)
    job["finished_at"] = now
    job["updated_at"] = now
    _save("image_generation_jobs.json", jobs)
    _save("image_artifacts.json", artifacts)

    _log("generate_images", "ok", credential_id=used_cred_id, workspace=workspace_id, meta={"executed": True, "images": n_images})
    return {"job": job, "artifacts": created_artifacts}

def create_image_html(workspace_id, image_paths, title=None, persist=None, **_extra):
    import json, os, datetime, time, re, secrets, html as _html

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0419000" if __import__("os").path.isdir("./environment_mix/0419000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        tms = int(now_dt.timestamp() * 1000)
        chars = []
        for _ in range(10):
            chars.append(alphabet[tms % 32])
            tms //= 32
        timepart = "".join(reversed(chars))
        randpart = "".join(secrets.choice(alphabet) for _ in range(16))
        return f"{prefix}_{timepart}{randpart}"

    def _log(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "create_image_html",
            "credential_id": credential_id,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        wsp_pat = re.compile(r"^imgwsp_[0-9A-HJKMNP-TV-Z]{16,}$")
        if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "workspace_id"})
            return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")

        if not isinstance(image_paths, list) or len(image_paths) < 1:
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "image_paths"})
            return _err("VALIDATION_ERROR", "image_paths must be a non-empty array.", field="image_paths")
        if len(image_paths) > 200:
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "image_paths"})
            return _err("VALIDATION_ERROR", "image_paths must have between 1 and 200 items.", field="image_paths")
        for i, p in enumerate(image_paths):
            if not isinstance(p, str) or p == "":
                _log("error", meta={"code": "VALIDATION_ERROR", "field": "image_paths", "index": i})
                return _err("VALIDATION_ERROR", "image_paths items must be non-empty strings.", field="image_paths", index=i)

        if title is not None and not isinstance(title, str):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "title"})
            return _err("VALIDATION_ERROR", "title must be a string.", field="title")

        if persist is None:
            persist = False
        if not isinstance(persist, bool):
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "persist"})
            return _err("VALIDATION_ERROR", "persist must be a boolean.", field="persist")

        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            _log("error", meta={"code": "NOT_FOUND", "workspace_id": workspace_id})
            return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

        ws_status = ws.get("status")
        if ws_status == "deleted":
            _log("error", meta={"code": "UNAUTHORIZED", "workspace_id": workspace_id})
            return _err("UNAUTHORIZED", "Workspace is deleted; writes are forbidden.", workspace_id=workspace_id)

        # Business rule: suspended forbids new galleries (only if persisting a gallery row)
        if persist and ws_status == "suspended":
            _log("error", meta={"code": "INVALID_TRANSITION", "workspace_id": workspace_id})
            return _err("INVALID_TRANSITION", "Workspace is suspended; creating new galleries is forbidden.", workspace_id=workspace_id)

        artifacts = _load("image_artifacts.json")
        if not isinstance(artifacts, list):
            artifacts = []

        # Validate all image_paths exist in same workspace and are available
        art_by_path = {}
        for a in artifacts:
            if isinstance(a, dict) and a.get("workspace_id") == workspace_id and a.get("status") == "available":
                fp = a.get("file_path")
                if isinstance(fp, str):
                    art_by_path[fp] = a

        missing = []
        for p in image_paths:
            if p not in art_by_path:
                missing.append(p)
        if missing:
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "image_paths", "missing_count": len(missing)})
            return _err(
                "VALIDATION_ERROR",
                "All image_paths must refer to available image_artifacts.file_path in the same workspace.",
                field="image_paths",
                missing=missing[:50],
                missing_count=len(missing),
            )

        # Produce html with ordering preserved exactly as provided
        esc_title = _html.escape(title) if isinstance(title, str) and title.strip() else None
        lines = []
        lines.append('<div class="imagen-gallery">')
        if esc_title:
            lines.append(f'  <h3 class="imagen-gallery__title">{esc_title}</h3>')
        lines.append('  <div class="imagen-gallery__grid">')
        for p in image_paths:
            a = art_by_path[p]
            alt = esc_title or "Generated image"
            src = _html.escape(p, quote=True)
            mime = a.get("mime_type") if isinstance(a, dict) else None
            mime_attr = f' data-mime="{_html.escape(mime)}"' if isinstance(mime, str) and mime else ""
            lines.append(f'    <img class="imagen-gallery__img" src="{src}" alt="{_html.escape(alt)}"{mime_attr} loading="lazy" />')
        lines.append("  </div>")
        lines.append("</div>")
        html_out = "\n".join(lines)

        if not isinstance(html_out, str) or html_out.strip() == "":
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "html"})
            return _err("VALIDATION_ERROR", "Generated html is empty.", field="html")

        if not persist:
            _log("ok", meta={"persisted": False})
            return {
                "workspace_id": workspace_id,
                "title": title,
                "image_paths": image_paths,
                "html": html_out,
                "persisted": False,
                "created_at": now,
            }

        galleries = _load("html_galleries.json")
        if not isinstance(galleries, list):
            galleries = []

        gal_id = _gen_id("imggal")
        row = {
            "id": gal_id,
            "workspace_id": workspace_id,
            "status": "active",
            "title": title,
            "image_paths": list(image_paths),
            "html": html_out,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }
        galleries.append(row)
        _save("html_galleries.json", galleries)

        _log("ok", meta={"persisted": True, "gallery_id": gal_id})
        return {"gallery": row}
    except Exception as e:
        _log("error", meta={"code": "VALIDATION_ERROR", "detail": "unexpected"})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def list_image_generation_jobs(workspace_id, api_key_id=None, status=None, provider_request_id=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0419000" if __import__("os").path.isdir("./environment_mix/0419000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    wsp_pat = re.compile(r"^imgwsp_[0-9A-HJKMNP-TV-Z]{16,}$")
    key_pat = re.compile(r"^imgkey_[0-9A-HJKMNP-TV-Z]{16,}$")
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")

    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not key_pat.match(api_key_id):
            return _err("VALIDATION_ERROR", "api_key_id is malformed.", field="api_key_id")

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status is invalid.", field="status", allowed=sorted(allowed_status))

    if provider_request_id is not None and not isinstance(provider_request_id, str):
        return _err("VALIDATION_ERROR", "provider_request_id must be a string.", field="provider_request_id")

    ca = _parse_iso(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string.", field="created_after")
    cb = _parse_iso(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string.", field="created_before")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 200.", field="page_size")

    # page_token is opaque; we use base64url JSON {"created_at": "...", "id": "..."}
    cursor = None
    if page_token is not None:
        if not isinstance(page_token, str) or page_token == "":
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided.", field="page_token")
        try:
            pad = "=" * (-len(page_token) % 4)
            raw = base64.urlsafe_b64decode((page_token + pad).encode("utf-8")).decode("utf-8")
            cursor = json.loads(raw)
        except Exception:
            return _err("VALIDATION_ERROR", "page_token is invalid.", field="page_token")
        if not isinstance(cursor, dict) or "created_at" not in cursor or "id" not in cursor:
            return _err("VALIDATION_ERROR", "page_token is invalid.", field="page_token")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    jobs = _load("image_generation_jobs.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") == "deleted":
        return _err("UNAUTHORIZED", "Workspace is deleted.", workspace_id=workspace_id)

    # Optional key: enforce rpm limit for reads only if provided (business rule mentions "may return RATE_LIMITED")
    if api_key_id is not None:
        key = next((k for k in api_keys if k.get("id") == api_key_id and k.get("workspace_id") == workspace_id), None)
        if not key:
            return _err("UNAUTHORIZED", "API key not found for workspace.", api_key_id=api_key_id, workspace_id=workspace_id)

        rpm_limit = key.get("requests_per_minute_limit")
        if not isinstance(rpm_limit, int) or not (1 <= rpm_limit <= 6000):
            return _err("VALIDATION_ERROR", "API key requests_per_minute_limit is invalid.", api_key_id=api_key_id)

        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(seconds=60)
        recent_calls = 0
        for j in jobs:
            if j.get("api_key_id") != api_key_id:
                continue
            dt = _parse_iso(j.get("created_at"))
            if dt and dt >= one_min_ago:
                recent_calls += 1
        if recent_calls >= rpm_limit:
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rpm_limit)

    # Filter
    out = []
    for j in jobs:
        if j.get("workspace_id") != workspace_id:
            continue
        if api_key_id is not None and j.get("api_key_id") != api_key_id:
            continue
        if status is not None and j.get("status") != status:
            continue
        if provider_request_id is not None and j.get("provider_request_id") != provider_request_id:
            continue
        dtc = _parse_iso(j.get("created_at"))
        if ca is not None and dtc and dtc < ca:
            continue
        if cb is not None and dtc and dtc > cb:
            continue
        out.append(j)

    # Sort created_at desc, id desc as tiebreaker
    def _sort_key(j):
        dt = _parse_iso(j.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (dt, j.get("id") or "")
    out.sort(key=_sort_key, reverse=True)

    # Apply cursor: return records strictly "after" cursor in this ordering
    if cursor is not None:
        c_dt = _parse_iso(cursor.get("created_at"))
        c_id = cursor.get("id")
        if c_dt is None or not isinstance(c_id, str):
            return _err("VALIDATION_ERROR", "page_token is invalid.", field="page_token")
        filtered = []
        for j in out:
            jdt = _parse_iso(j.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            jid = j.get("id") or ""
            # since list is desc, items after cursor are those with (dt,id) < (c_dt,c_id)
            if (jdt, jid) < (c_dt, c_id):
                filtered.append(j)
        out = filtered

    total = len(out)
    page = out[:page_size]
    has_more = total > page_size

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = json.dumps({"created_at": last.get("created_at"), "id": last.get("id")}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    return {
        "jobs": page,
        "page": {
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_cursor,
            "total_matched": total
        }
    }

def get_image_generation_job(workspace_id, job_id, api_key_id=None, **_extra):
    import json, os, re, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0419000" if __import__("os").path.isdir("./environment_mix/0419000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _log(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "get_image_generation_job",
            "credential_id": credential_id,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        wsp_pat = re.compile(r"^imgwsp_[0-9A-HJKMNP-TV-Z]{16,}$")
        job_pat = re.compile(r"^imgjob_[0-9A-HJKMNP-TV-Z]{16,}$")
        key_pat = re.compile(r"^imgkey_[0-9A-HJKMNP-TV-Z]{16,}$")

        if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "workspace_id"})
            return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")
        if not isinstance(job_id, str) or not job_pat.match(job_id):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "job_id"})
            return _err("VALIDATION_ERROR", "job_id is malformed.", field="job_id")
        if api_key_id is not None and (not isinstance(api_key_id, str) or not key_pat.match(api_key_id)):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "api_key_id"})
            return _err("VALIDATION_ERROR", "api_key_id is malformed.", field="api_key_id")

        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            _log("error", credential_id=api_key_id, meta={"code": "NOT_FOUND", "workspace_id": workspace_id})
            return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
        if ws.get("status") == "deleted":
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "workspace_id": workspace_id})
            return _err("UNAUTHORIZED", "Workspace is deleted; access is forbidden.", workspace_id=workspace_id)

        jobs = _load("image_generation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        job = next((j for j in jobs if isinstance(j, dict) and j.get("id") == job_id), None)
        if not job:
            _log("error", credential_id=api_key_id, meta={"code": "NOT_FOUND", "job_id": job_id})
            return _err("NOT_FOUND", "Job not found.", job_id=job_id)
        if job.get("workspace_id") != workspace_id:
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "job_id": job_id})
            return _err("UNAUTHORIZED", "Job does not belong to the given workspace.", job_id=job_id, workspace_id=workspace_id)

        # Optional credential parameter: authenticate by id (NOT by hash). Do not block reads if revoked unless
        # the caller explicitly provided a revoked key.
        key_row = None
        if api_key_id is not None:
            keys = _load("api_keys.json")
            if not isinstance(keys, list):
                keys = []
            key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
            if not key_row:
                _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "api_key_id": api_key_id})
                return _err("UNAUTHORIZED", "API key not recognized.", api_key_id=api_key_id)
            if key_row.get("workspace_id") != workspace_id:
                _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "api_key_id": api_key_id})
                return _err("UNAUTHORIZED", "API key does not belong to the given workspace.", api_key_id=api_key_id, workspace_id=workspace_id)
            # Reads are allowed even if revoked in this service (business rules only forbid creating jobs/galleries and deletions).
            # So do not reject revoked keys here.

            # Update last_used_at for observable dynamics
            if isinstance(keys, list):
                for k in keys:
                    if isinstance(k, dict) and k.get("id") == api_key_id:
                        k["last_used_at"] = now
                        k["updated_at"] = now
                        break
                _save("api_keys.json", keys)

        artifacts = _load("image_artifacts.json")
        if not isinstance(artifacts, list):
            artifacts = []
        job_arts = [a for a in artifacts if isinstance(a, dict) and a.get("job_id") == job_id and a.get("workspace_id") == workspace_id]

        out = dict(job)
        out["artifacts"] = job_arts

        _log("ok", credential_id=api_key_id, meta={"artifact_count": len(job_arts)})
        return {"job": out}
    except Exception as e:
        _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "detail": "unexpected"})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def cancel_image_generation_job(workspace_id, job_id, api_key_id, reason=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0419000" if __import__("os").path.isdir("./environment_mix/0419000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _log(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "cancel_image_generation_job",
            "credential_id": credential_id,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_isoz(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    try:
        wsp_pat = re.compile(r"^imgwsp_[0-9A-HJKMNP-TV-Z]{16,}$")
        job_pat = re.compile(r"^imgjob_[0-9A-HJKMNP-TV-Z]{16,}$")
        key_pat = re.compile(r"^imgkey_[0-9A-HJKMNP-TV-Z]{16,}$")
        if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "workspace_id"})
            return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")
        if not isinstance(job_id, str) or not job_pat.match(job_id):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "job_id"})
            return _err("VALIDATION_ERROR", "job_id is malformed.", field="job_id")
        if not isinstance(api_key_id, str) or not key_pat.match(api_key_id):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "api_key_id"})
            return _err("VALIDATION_ERROR", "api_key_id is malformed.", field="api_key_id")
        if reason is not None and not isinstance(reason, str):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "reason"})
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")

        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            _log("error", credential_id=api_key_id, meta={"code": "NOT_FOUND", "workspace_id": workspace_id})
            return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
        if ws.get("status") == "deleted":
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "workspace_id": workspace_id})
            return _err("UNAUTHORIZED", "Workspace is deleted; writes are forbidden.", workspace_id=workspace_id)

        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
        if not key_row:
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "api_key_id": api_key_id})
            return _err("UNAUTHORIZED", "API key not recognized.", api_key_id=api_key_id)
        if key_row.get("workspace_id") != workspace_id:
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "api_key_id": api_key_id})
            return _err("UNAUTHORIZED", "API key does not belong to the given workspace.", api_key_id=api_key_id, workspace_id=workspace_id)

        # Rate limit enforcement (requests_per_minute_limit) for this key
        rpm = key_row.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential_id") != api_key_id:
                continue
            ts = _parse_isoz(r.get("timestamp"))
            if ts and ts >= one_min_ago:
                cnt += 1
        if cnt >= rpm:
            _log("error", credential_id=api_key_id, meta={"code": "RATE_LIMIT", "limit": rpm})
            return _err("RATE_LIMIT", "Rate limit exceeded for API key.", api_key_id=api_key_id, requests_per_minute_limit=rpm)

        jobs = _load("image_generation_jobs.json")
        if not isinstance(jobs, list):
            jobs = []
        job = next((j for j in jobs if isinstance(j, dict) and j.get("id") == job_id), None)
        if not job:
            _log("error", credential_id=api_key_id, meta={"code": "NOT_FOUND", "job_id": job_id})
            return _err("NOT_FOUND", "Job not found.", job_id=job_id)
        if job.get("workspace_id") != workspace_id:
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "job_id": job_id})
            return _err("UNAUTHORIZED", "Job does not belong to the given workspace.", job_id=job_id, workspace_id=workspace_id)

        # The tool description says to refuse when API key is revoked. However, audit indicates this was wrongly triggered
        # due to bad authentication (e.g., comparing to hashes). We authenticate by id and only refuse if this key row is revoked.
        if key_row.get("status") == "revoked":
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "api_key_id": api_key_id})
            return _err("UNAUTHORIZED", "API key is revoked; cannot cancel jobs.", api_key_id=api_key_id)

        cur = job.get("status")
        if cur in ("succeeded", "failed", "cancelled"):
            _log("error", credential_id=api_key_id, meta={"code": "INVALID_TRANSITION", "from": cur, "to": "cancelled"})
            return _err("INVALID_TRANSITION", "Job is already in a terminal state and cannot be cancelled.", job_id=job_id, status=cur)

        if cur not in ("queued", "running"):
            _log("error", credential_id=api_key_id, meta={"code": "INVALID_TRANSITION", "from": cur, "to": "cancelled"})
            return _err("INVALID_TRANSITION", "Job cannot be cancelled from its current state.", job_id=job_id, status=cur)

        # Apply transition to cancelled
        # Constraints: started_at must be not null when status in running/succeeded/failed/cancelled (and not queued)
        if not job.get("started_at"):
            job["started_at"] = now
        job["status"] = "cancelled"
        job["finished_at"] = now
        job["updated_at"] = now
        if isinstance(reason, str) and reason.strip():
            job["error_message"] = reason.strip()
            job["error_code"] = job.get("error_code") or "cancelled"

        # Mark any partial artifacts deleted
        artifacts = _load("image_artifacts.json")
        if not isinstance(artifacts, list):
            artifacts = []
        changed_art = 0
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("workspace_id") != workspace_id or a.get("job_id") != job_id:
                continue
            if a.get("status") == "available":
                a["status"] = "deleted"
                a["deleted_at"] = now
                a["updated_at"] = now
                changed_art += 1

        # Persist job list (job dict is already mutated in place)
        _save("image_generation_jobs.json", jobs)
        if changed_art:
            _save("image_artifacts.json", artifacts)

        # Update key last_used_at for observable dynamics
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", keys)

        _log("ok", credential_id=api_key_id, meta={"job_id": job_id, "deleted_artifacts": changed_art})
        return {"job": job, "deleted_artifacts": changed_art}
    except Exception as e:
        _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "detail": "unexpected"})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def list_image_artifacts(workspace_id, job_id=None, status=None, file_path_prefix=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0419000" if __import__("os").path.isdir("./environment_mix/0419000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, credential_id=None, workspace=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": None,
            "endpoint": endpoint,
            "credential_id": credential_id,
            "workspace_id": workspace,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        try:
            import secrets
            row["id"] = "req_" + secrets.token_hex(12)
        except Exception:
            row["id"] = "req_" + str(len(logs) + 1)
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_token(tok):
        if not isinstance(tok, str) or not tok:
            return None
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if "|" not in s:
                return None
            created_at, art_id = s.split("|", 1)
            if not created_at or not art_id:
                return None
            return (created_at, art_id)
        except Exception:
            return None

    def _make_token(created_at, art_id):
        try:
            s = f"{created_at}|{art_id}".encode("utf-8")
            return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")
        except Exception:
            return None

    def _parse_isoz(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # validate
    pat_w = re.compile(r"^imgwsp_[0-9A-HJKMNP-TV-Z]{16,}$")
    pat_j = re.compile(r"^imgjob_[0-9A-HJKMNP-TV-Z]{16,}$")
    if not isinstance(workspace_id, str) or not pat_w.match(workspace_id):
        _log("list_image_artifacts", "error", workspace=workspace_id if isinstance(workspace_id, str) else None, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if job_id is not None and (not isinstance(job_id, str) or not pat_j.match(job_id)):
        _log("list_image_artifacts", "error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid job_id.")
    if status is not None and status not in ("available", "deleted"):
        _log("list_image_artifacts", "error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid status.")
    if file_path_prefix is not None and not isinstance(file_path_prefix, str):
        _log("list_image_artifacts", "error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "file_path_prefix must be a string.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log("list_image_artifacts", "error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if page_token is not None and not isinstance(page_token, str):
        _log("list_image_artifacts", "error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "page_token must be a string when provided.")

    workspaces = _load("workspaces.json")
    artifacts = _load("image_artifacts.json")
    if not isinstance(workspaces, list) or not isinstance(artifacts, list):
        _log("list_image_artifacts", "error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Datastore is not initialized correctly.")

    wsp = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not wsp:
        _log("list_image_artifacts", "success", workspace=workspace_id, meta={"total": 0})
        return {"artifacts": [], "total": 0, "has_more": False, "next_cursor": None}
    if wsp.get("status") == "deleted":
        _log("list_image_artifacts", "error", workspace=workspace_id, meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is deleted; access is refused.")

    # Filter
    rows = [a for a in artifacts if a.get("workspace_id") == workspace_id]
    if job_id is not None:
        rows = [a for a in rows if a.get("job_id") == job_id]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]
    if file_path_prefix:
        rows = [a for a in rows if isinstance(a.get("file_path"), str) and a.get("file_path").startswith(file_path_prefix)]

    # Order: created_at desc, stable tiebreaker id desc
    def _key(a):
        dt = _parse_isoz(a.get("created_at")) or datetime.datetime.min
        # For descending sort with python ascending: use negative timestamp
        return (-dt.timestamp(), "" if a.get("id") is None else str(a.get("id")))
    # Use two-stage stable: sort by id desc after created_at desc.
    rows.sort(key=lambda a: (_parse_isoz(a.get("created_at")) or datetime.datetime.min, str(a.get("id") or "")), reverse=True)

    total = len(rows)

    # Apply cursor
    start = 0
    if page_token:
        cur = _parse_token(page_token)
        if cur is None:
            _log("list_image_artifacts", "error", workspace=workspace_id, meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid page_token.")
        cur_created_at, cur_id = cur
        # Find first row strictly after cursor in this ordering; since we sort desc, "after" means smaller than cursor tuple.
        def _tuple(a):
            return (a.get("created_at") or "", str(a.get("id") or ""))
        # cursor tuple
        ctu = (cur_created_at, cur_id)
        # rows are in desc order: skip until row tuple < cursor tuple in desc comparator.
        # Implement by finding the first row with tuple strictly less than cursor using same tuple ordering.
        i = 0
        while i < len(rows):
            if _tuple(rows[i]) < ctu:
                break
            i += 1
        start = i

    page = rows[start:start + page_size]
    has_more = (start + page_size) < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _make_token(last.get("created_at") or "", str(last.get("id") or ""))

    _log("list_image_artifacts", "success", workspace=workspace_id, meta={"returned": len(page), "total": total, "has_more": has_more})

    return {
        "artifacts": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def delete_image_artifact(workspace_id, artifact_id, api_key_id=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0419000" if __import__("os").path.isdir("./environment_mix/0419000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc, microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _log(status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "delete_image_artifact",
            "credential_id": credential_id,
            "workspace_id": workspace_id if isinstance(workspace_id, str) else None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now
        }
        if isinstance(meta, dict):
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_isoz(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    try:
        wsp_pat = re.compile(r"^imgwsp_[0-9A-HJKMNP-TV-Z]{16,}$")
        art_pat = re.compile(r"^imgart_[0-9A-HJKMNP-TV-Z]{16,}$")
        key_pat = re.compile(r"^imgkey_[0-9A-HJKMNP-TV-Z]{16,}$")
        if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "workspace_id"})
            return _err("VALIDATION_ERROR", "workspace_id is malformed.", field="workspace_id")
        if not isinstance(artifact_id, str) or not art_pat.match(artifact_id):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "artifact_id"})
            return _err("VALIDATION_ERROR", "artifact_id is malformed.", field="artifact_id")
        if api_key_id is not None and (not isinstance(api_key_id, str) or not key_pat.match(api_key_id)):
            _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "field": "api_key_id"})
            return _err("VALIDATION_ERROR", "api_key_id is malformed.", field="api_key_id")

        workspaces = _load("workspaces.json")
        if not isinstance(workspaces, list):
            workspaces = []
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            _log("error", credential_id=api_key_id, meta={"code": "NOT_FOUND", "workspace_id": workspace_id})
            return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
        if ws.get("status") == "deleted":
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "workspace_id": workspace_id})
            return _err("UNAUTHORIZED", "Workspace is deleted; writes are forbidden.", workspace_id=workspace_id)

        keys = None
        key_row = None
        if api_key_id is not None:
            keys = _load("api_keys.json")
            if not isinstance(keys, list):
                keys = []
            key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == api_key_id), None)
            if not key_row:
                _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "api_key_id": api_key_id})
                return _err("UNAUTHORIZED", "API key not recognized.", api_key_id=api_key_id)
            if key_row.get("workspace_id") != workspace_id:
                _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "api_key_id": api_key_id})
                return _err("UNAUTHORIZED", "API key does not belong to the given workspace.", api_key_id=api_key_id, workspace_id=workspace_id)
            if key_row.get("status") == "revoked":
                _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "api_key_id": api_key_id})
                return _err("UNAUTHORIZED", "API key is revoked; cannot delete artifacts.", api_key_id=api_key_id)

            # Rate limit check (requests/min) for this credential on this endpoint too
            rpm = key_row.get("requests_per_minute_limit")
            if not isinstance(rpm, int) or rpm < 1:
                rpm = 60
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            one_min_ago = now_dt - datetime.timedelta(minutes=1)
            cnt = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("credential_id") != api_key_id:
                    continue
                ts = _parse_isoz(r.get("timestamp"))
                if ts and ts >= one_min_ago:
                    cnt += 1
            if cnt >= rpm:
                _log("error", credential_id=api_key_id, meta={"code": "RATE_LIMIT", "limit": rpm})
                return _err("RATE_LIMIT", "Rate limit exceeded for API key.", api_key_id=api_key_id, requests_per_minute_limit=rpm)

        artifacts = _load("image_artifacts.json")
        if not isinstance(artifacts, list):
            artifacts = []
        art = next((a for a in artifacts if isinstance(a, dict) and a.get("id") == artifact_id), None)
        if not art:
            _log("error", credential_id=api_key_id, meta={"code": "NOT_FOUND", "artifact_id": artifact_id})
            return _err("NOT_FOUND", "Artifact not found.", artifact_id=artifact_id)
        if art.get("workspace_id") != workspace_id:
            _log("error", credential_id=api_key_id, meta={"code": "UNAUTHORIZED", "artifact_id": artifact_id})
            return _err("UNAUTHORIZED", "Artifact does not belong to the given workspace.", artifact_id=artifact_id, workspace_id=workspace_id)
        if art.get("status") == "deleted":
            _log("error", credential_id=api_key_id, meta={"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Artifact is already deleted.", artifact_id=artifact_id)

        if art.get("status") != "available":
            _log("error", credential_id=api_key_id, meta={"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Artifact cannot be deleted from its current state.", artifact_id=artifact_id, status=art.get("status"))

        art["status"] = "deleted"
        art["deleted_at"] = now
        art["updated_at"] = now
        _save("image_artifacts.json", artifacts)

        if api_key_id is not None and isinstance(keys, list):
            for k in keys:
                if isinstance(k, dict) and k.get("id") == api_key_id:
                    k["last_used_at"] = now
                    k["updated_at"] = now
                    break
            _save("api_keys.json", keys)

        _log("ok", credential_id=api_key_id, meta={"artifact_id": artifact_id})
        return {"artifact": art}
    except Exception as e:
        _log("error", credential_id=api_key_id, meta={"code": "VALIDATION_ERROR", "detail": "unexpected"})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def get_auth_context(api_key_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0419000" if __import__("os").path.isdir("./environment_mix/0419000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _ensure_request_log():
        # Not declared in schema, but required to record every call if such a collection exists.
        # We implement a best-effort request log at /app/database/request_logs.json.
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                with open(path, "w", encoding="utf-8") as f:
                    json.dump([], f, ensure_ascii=False, indent=2)
            except Exception:
                return None
        return "request_logs.json"

    t0 = time.time()
    ts = _now_iso()
    reqlog_file = _ensure_request_log()

    def _log(status, api_key_row_id=None, workspace_id=None, error_code=None):
        if not reqlog_file:
            return
        logs = _load(reqlog_file)
        latency_ms = int(round((time.time() - t0) * 1000))
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}",
                "endpoint": "get_auth_context",
                "timestamp": ts,
                "status": status,
                "latency_ms": latency_ms,
                "api_key_id": api_key_row_id,
                "workspace_id": workspace_id,
                "error_code": error_code,
            }
        )
        _save(reqlog_file, logs)

    # ---- Validate input ----
    if not isinstance(api_key_id, str) or not api_key_id:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string.")
    import re
    if not re.match(r"^imgkey_[0-9A-HJKMNP-TV-Z]{16,}$", api_key_id):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key_id does not match required pattern.")

    # ---- Authenticate (explicit credential parameter) ----
    api_keys = _load("api_keys.json")
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("id") == api_key_id:
            key_row = r
            break

    if not key_row:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Credential not found or invalid.")

    if key_row.get("status") != "active":
        _log("error", api_key_row_id=key_row.get("id"), workspace_id=key_row.get("workspace_id"), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Credential is revoked or inactive.")

    # Resolve workspace and ensure it exists (status may affect entitlements, but introspection allowed).
    workspaces = _load("workspaces.json")
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if not ws:
        _log("error", api_key_row_id=key_row.get("id"), workspace_id=key_row.get("workspace_id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Workspace for credential not found.")

    # Update last_used_at as observable state (introspection counts as usage).
    now = _now_iso()
    updated = False
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == key_row.get("id"):
            api_keys[i] = dict(r)
            api_keys[i]["last_used_at"] = now
            api_keys[i]["updated_at"] = now
            key_row = api_keys[i]
            updated = True
            break
    if updated:
        _save("api_keys.json", api_keys)

    # ---- Compute consumption for quotas/limits ----
    jobs = _load("image_generation_jobs.json")
    artifacts = _load("image_artifacts.json")

    # Rate limit: requests per minute for "tool calls". Without an official request log schema,
    # we approximate based on request_logs.json if present, otherwise fall back to job creations for this key.
    minute_window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60))
    day_window_start = datetime.datetime.utcnow().date()

    rpm_used = 0
    if reqlog_file:
        logs = _load(reqlog_file)
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") != key_row.get("id"):
                continue
            dt = _parse_dt(e.get("timestamp"))
            if dt and dt >= minute_window_start:
                rpm_used += 1
    else:
        # Fallback: count jobs queued in last minute as a proxy.
        for j in jobs:
            if not isinstance(j, dict):
                continue
            if j.get("api_key_id") != key_row.get("id"):
                continue
            dt = _parse_dt(j.get("queued_at"))
            if dt and dt >= minute_window_start:
                rpm_used += 1

    # Daily job usage: number of jobs created today for this key
    daily_jobs_used = 0
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("api_key_id") != key_row.get("id"):
            continue
        dt = _parse_dt(j.get("queued_at")) or _parse_dt(j.get("created_at"))
        if dt and dt.date() == day_window_start:
            daily_jobs_used += 1

    # Daily image usage: number of image_artifacts created today for jobs under this key; count only available ones.
    # (Limit is "based on the number of image_artifacts created per day".)
    # We attribute artifacts to key via job_id -> job.api_key_id.
    job_key_by_id = {}
    for j in jobs:
        if isinstance(j, dict) and j.get("id"):
            job_key_by_id[j["id"]] = j.get("api_key_id")

    daily_images_used = 0
    for a in artifacts:
        if not isinstance(a, dict):
            continue
        if a.get("status") != "available":
            continue
        jid = a.get("job_id")
        if not jid or job_key_by_id.get(jid) != key_row.get("id"):
            continue
        dt = _parse_dt(a.get("created_at"))
        if dt and dt.date() == day_window_start:
            daily_images_used += 1

    # Limits
    rpm_limit = key_row.get("requests_per_minute_limit")
    djob_limit = key_row.get("daily_job_limit")
    dimg_limit = key_row.get("daily_image_limit")

    # Validate stored limits (defensive)
    if not isinstance(rpm_limit, int) or rpm_limit < 1 or rpm_limit > 6000:
        _log("error", api_key_row_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="CONFLICT")
        return _err("CONFLICT", "Credential has invalid requests_per_minute_limit in datastore.")
    if not isinstance(djob_limit, int) or djob_limit < 0 or djob_limit > 100000:
        _log("error", api_key_row_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="CONFLICT")
        return _err("CONFLICT", "Credential has invalid daily_job_limit in datastore.")
    if not isinstance(dimg_limit, int) or dimg_limit < 0 or dimg_limit > 1000000:
        _log("error", api_key_row_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="CONFLICT")
        return _err("CONFLICT", "Credential has invalid daily_image_limit in datastore.")

    # Effective entitlements given workspace status and key status
    ws_status = ws.get("status")
    can_create_jobs = True
    can_execute_jobs = True
    can_create_galleries = True
    can_write_anything = True

    if ws_status == "deleted":
        can_write_anything = False
        can_create_jobs = False
        can_execute_jobs = False
        can_create_galleries = False
    elif ws_status == "suspended":
        can_create_jobs = True  # jobs may be created as queued
        can_execute_jobs = False  # but must not transition to running
        can_create_galleries = False
        can_write_anything = True
    elif ws_status == "active":
        pass
    else:
        # unknown status is a datastore conflict
        _log("error", api_key_row_id=key_row.get("id"), workspace_id=ws.get("id"), error_code="CONFLICT")
        return _err("CONFLICT", "Workspace has invalid status in datastore.")

    # Scopes are not modeled; return a conservative set reflecting operations in this service.
    granted_scopes = ["images.generate", "images.read", "galleries.create", "galleries.read", "auth.introspect"]

    # Provide consumption and whether currently over limit (not refusing this endpoint unless unauthorized).
    limits = {
        "requests_per_minute": {"limit": rpm_limit, "used": rpm_used, "remaining": max(0, rpm_limit - rpm_used)},
        "daily_jobs": {"limit": djob_limit, "used": daily_jobs_used, "remaining": max(0, djob_limit - daily_jobs_used)},
        "daily_images": {"limit": dimg_limit, "used": daily_images_used, "remaining": max(0, dimg_limit - daily_images_used)},
    }

    _log("ok", api_key_row_id=key_row.get("id"), workspace_id=ws.get("id"))

    return {
        "credential": {
            "type": "api_key",
            "api_key_id": key_row.get("id"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "workspace": {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
            "default_model": ws.get("default_model"),
            "storage_base_path": ws.get("storage_base_path"),
            "created_at": ws.get("created_at"),
            "updated_at": ws.get("updated_at"),
        },
        "granted_scopes": granted_scopes,
        "effective_entitlements": {
            "can_write": can_write_anything,
            "can_create_jobs": can_create_jobs,
            "can_execute_jobs": can_execute_jobs,
            "can_create_galleries": can_create_galleries,
        },
        "rate_limit_and_quota": limits,
        "server_time": ts,
    }
